"""Freeze one previously identified metadata-SNR candidate; no network or arrays."""
import datetime,hashlib,json
from pathlib import Path
HERE=Path(__file__).resolve().parent
REPO=HERE.parents[1]
OLD=REPO/'work_harps_20261102_berv_followup'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_bytes())
def rel(p):return str(p.relative_to(REPO))
assert not (HERE/'HEADER_STARTED.json').exists() and not (HERE/'PAYLOAD_STARTED.json').exists()
c=read(HERE/'CANDIDATE.json');handoff=read(OLD/'next_followup/HANDOFF.json')
assert c==handoff['proposed_next_phase']['candidate'] and c['dp_id']=='ADP.2017-05-21T01:01:50.278' and c['source_file_ids']==['HARPS.2017-05-20T02:21:45.847']
pool=read(OLD/'metadata_search_v2/CANDIDATES.json');used={r['dp_id'] for r in read(OLD/'science_acquisition/PLAN.json')['inputs']}
origin=datetime.datetime(1858,11,17,tzinfo=datetime.timezone.utc)
eligible=[r for r in pool if r['dp_id'] not in used and r['target']=='HD122640' and (origin+datetime.timedelta(days=r['metadata']['t_min'])).strftime('%Y-%m')=='2017-05']
assert len(eligible)==9 and sorted(eligible,key=lambda r:(-r['metadata']['snr'],r['dp_id']))[0]==c
events=[{'candidate_id':r['candidate_id'],'discovery_dp_id':r['discovery_dp_id'],'discovery_berv_km_s':r['discovery_berv_km_s']} for r in read(OLD/'prospective_comparison/EVENTS.json') if r['target']=='HD122640']
assert [r['candidate_id'] for r in events]==['V2E2-0229','V2E2-0231','V2E2-0234','V2E2-0235','V2E2-0236','V2E2-0237']
sources=[OLD/'next_followup/HANDOFF.json',OLD/'metadata_search_v2/CANDIDATES.json',OLD/'metadata_search_v2/SCHEMA_CONTRACT.json',OLD/'science_acquisition/PLAN.json',OLD/'prospective_comparison/EVENTS.json',OLD/'header_acquisition_v2/header_tools.py',OLD/'header_acquisition_v2/docs/URL_BUILDER_RECEIPT.json',OLD/'header_acquisition_v2/docs/URL_BUILDER_RESPONSE.txt',OLD/'science_acquisition/DIRECT_FILE_CONTRACT.json',REPO/'work_harps_20261101/v2/CURRENT_V2_DISPOSITIONS.csv']
assert sha(HERE/'header_tools.py')==sha(OLD/'header_acquisition_v2/header_tools.py')
job={'job_index':0,'target':'HD122640','month_number':5,'dp_id':c['dp_id'],'source_file_ids':c['source_file_ids'],'metadata':c['metadata']}
plan={'schema':'HARPS_MAY_QUALITY_ACQUISITION_PLAN_V1','status':'PROSPECTIVE_POSTHOC_QUALITY_PHASE_NOT_EXECUTED','candidate_path':rel(HERE/'CANDIDATE.json'),'candidate_sha256':sha(HERE/'CANDIDATE.json'),'selection_rule':'Highest finite positive saved ObsCore average SNR among nine unused HD122640 observations in May 2017; ties lexicographically smallest dp_id. This quality phase was motivated posthoc by low continuum in the completed May reference; no unseen line flux enters selection.','job':job,'berv_gate':{'c_km_s':299792.458,'resolving_power':115000,'minimum_resolution_elements':10,'minimum_absolute_delta_km_s':10*299792.458/115000,'comparison':'>=','requirement':'Absolute candidate BERV displacement from EACH of the six preserved discovery BERV values must meet the threshold. Repeated discovery exposures remain six explicit checks.','meaning':'Descriptive large-shift planning benchmark, not classification, sensitivity or power; no need to extend the known 40.3634787209574 km/s range.','discovery_events':events},'header':{'url':'https://archive.eso.org/hdr?DpId='+c['dp_id'],'timeout_seconds':30,'max_response_bytes':524288,'attempts':1,'retries':0,'redirects':0},'payload':{'url':'https://dataportal.eso.org/dataPortal/file/'+c['dp_id'],'metadata_access_url':c['metadata']['access_url'],'timeout_seconds':60,'max_response_bytes':16777216,'attempts':1,'retries':0,'redirects':0,'optional_only_after_separate_root_release':True},'limits':{'maximum_header_requests':1,'maximum_payload_requests':1,'maximum_total_requests':2,'substitution':False,'new_arrays_interpreted_by_acquisition':0},'identity_checks':'Unchanged checked header_tools: exact ADP/raw provenance, HD122640, HARPS, date/MJD/exposure/coordinates within inherited tolerances, NCOMBINE 1, SPEC_RES 115000, BARYCENT. Require explicit HEFS false, finite coordinate range and DATE-OBS matching exact raw timestamp within 0.02 s. Preserve pipeline differences.','payload_representation':'Check complete exact primary provenance, NAXIS=0, recorded primary headers and one-row binary table WAVE/FLUX/ERR; same positive fixed numeric-real vector lengths, air-Angstrom WAVE, ADU FLUX, unique column names and HEFS false before any HDU.data access. No arrays accessed by acquisition.','release_contract':{'freeze_path':rel(HERE.parent/'PREFLIGHT_FREEZE.json'),'header_release':'HEADER_RELEASE.json','payload_release':'PAYLOAD_RELEASE.json','requirement':'Root publishes all prospective acquisition/comparison methods before header. Exact stage release binds freeze, candidate, plan, code and successful exact-remote publication receipt. Optional payload release additionally binds verified header results, selection, header release and published original header/receipt evidence.','no_network_default':True},'source_hashes':{rel(p):sha(p) for p in sources},'code_hashes':{n:sha(HERE/n) for n in ['acquire.py','header_tools.py','prepare_plan.py']},'original_counts':{'main_survey_exposures':300,'V2_records':669,'A':403,'O':46,'U':185,'M':35,'N':0},'no_original_classification_changes':True,'current24_profile_run_immutable':True,'failure_rule':'Any header/identity/displacement/transfer/representation failure stops the one-candidate phase. Preserve failed bytes and status; no retry, next-best substitution or scope expansion.'}
(HERE/'PLAN.json').write_text(json.dumps(plan,indent=2)+'\n')
print(json.dumps({'plan_sha256':sha(HERE/'PLAN.json'),'candidate_sha256':sha(HERE/'CANDIDATE.json'),'minimum_absolute_delta_km_s':plan['berv_gate']['minimum_absolute_delta_km_s']},indent=2))
